    return s.str.upper()

Then try to import this module in a main script before SparkSession is created, or run spark-submit on it.

import org.apache.spark.sql.{Row, SparkSession}
import org.apache.spark.sql.types._
val rdd = sc.parallelize(Seq(Row((-128).toByte)))
val schema = new StructType().add(StructField("c1", ByteType, true))
val df = spark.createDataFrame(rdd, schema)
df.write.mode("overwrite").format("avro").saveAsTable(
  "byte_avro"
)

// Then in spark-sql:
select * from byte_avro;
